from pathlib import Path
import random,json,hashlib
p=Path(__file__).parent;o=p/'custom';o.mkdir(exist_ok=True);rng=random.Random(61022);rows=[]
def write(name,n,ops):
 assert len(ops)==200000
 f=o/(name+'.in');f.write_text(f'{n} {len(ops)}\n'+'\n'.join(' '.join(map(str,x))for x in ops)+'\n');rows.append(dict(name=f.name,bytes=f.stat().st_size,sha256=hashlib.sha256(f.read_bytes()).hexdigest(),n=n,q=len(ops)))
n=131072;ops=[]
for k in range(17):
 step=1<<k
 for i in range(0,n,step*2):ops.append((0,i,i+step))
while len(ops)<200000:ops.append((1,rng.randrange(n),rng.randrange(n)))
write('balanced',n,ops)
n=65536;ops=[(0,0,i)for i in range(1,n)]
while len(ops)<200000:ops.append((int(len(ops)%4!=0),rng.randrange(n),rng.randrange(n)))
write('star_redundant',n,ops)
n=131072;ops=[]
for k in range(17):
 step=1<<k
 for i in range(0,n,step*2):ops.append((0,i,i+step))
while len(ops)<200000:
 v=rng.randrange(n);ops.append((1,v,v))
write('same_index_balanced',n,ops)
n=200000;ops=[]
for i in range(n//2):ops.append((0,2*i,2*i+1));ops.append((1,2*i,(2*i+4)%n))
write('disconnected_pairs',n,ops)
n=32;ops=[(rng.randrange(2),rng.randrange(n),rng.randrange(n))for _ in range(200000)];write('tiny_random',n,ops)
(p/'custom_cases.json').write_text(json.dumps(rows,indent=2)+'\n');print('custom',len(rows))

