#include <iostream>
#include <numeric>
#include <utility>
#include <vector>
// 親の木を使わず、小さい成分の全頂点に成分IDを書き直す独立参照。
int main() {
    std::ios::sync_with_stdio(false); std::cin.tie(nullptr);
    int n,q; if(!(std::cin>>n>>q)) return 0;
    std::vector<int> owner(n); std::iota(owner.begin(),owner.end(),0);
    std::vector<std::vector<int>> members(n);
    for(int i=0;i<n;++i) members[i].push_back(i);
    while(q--) {
        int type,u,v; std::cin>>type>>u>>v;
        if(type==1) { std::cout<<(owner[u]==owner[v])<<'\n'; continue; }
        int a=owner[u],b=owner[v]; if(a==b) continue;
        if(members[a].size()>members[b].size()) std::swap(a,b);
        for(int w:members[a]) { owner[w]=b; members[b].push_back(w); }
        std::vector<int>{}.swap(members[a]);
    }
}

