from pathlib import Path
import subprocess,random,json,hashlib,collections
p=Path(__file__).parent;sha=lambda b:hashlib.sha256(b).hexdigest();cmd=['taskset','-c','6','g++','-std=c++23','-O2','-Wall','-Wextra','-Werror','-pedantic-errors',str(p/'reference.cpp'),'-o',str(p/'reference')];subprocess.run(cmd,capture_output=True,check=True);rng=random.Random(61022)
for case in range(300):
 n=rng.randrange(1,33);q=rng.randrange(1,401);g=[[]for _ in range(n)];ops=[];expected=[]
 for _ in range(q):
  t=rng.randrange(2);u=rng.randrange(n);v=rng.randrange(n);ops.append((t,u,v))
  if not t:g[u].append(v);g[v].append(u);continue
  seen={u};todo=collections.deque([u])
  while todo:
   a=todo.popleft()
   for b in g[a]:
    if b not in seen:seen.add(b);todo.append(b)
  expected.append(int(v in seen))
 data=(f'{n} {q}\n'+'\n'.join(' '.join(map(str,x))for x in ops)+'\n').encode();out=subprocess.check_output([str(p/'reference')],input=data);assert list(map(int,out.split()))==expected,case
(p/'reference_selfcheck.json').write_text(json.dumps(dict(status='PASS',cases=300,seed=61022,method='独立した無向グラフBFSで各sameを照合',build_command=cmd),ensure_ascii=False,indent=2)+'\n');o=p/'reference_outputs';o.mkdir(exist_ok=True);rows=[]
for scope in ['official','custom']:
 for case in json.loads((p/(scope+'_cases.json')).read_text()):
  f=p/scope/case['name'];out=subprocess.check_output([str(p/'reference')],input=f.read_bytes());(o/(f.name+'.out')).write_bytes(out);rows.append(dict(case=f.name,scope=scope,input_sha256=sha(f.read_bytes()),output_sha256=sha(out),answers=len(out.split())))
(p/'official_reference.json').write_text(json.dumps(rows,indent=2)+'\n');print('reference PASS selfcheck300+inputs',len(rows))
